"""``velocia datagen --suite tera|text``: job input generated by Spark (docs/03-spec.md §2).

``tera``: TeraSort records (10-byte key, 90-byte value). ``text``: lines of ten words from a
skewed 50,000-word vocabulary, for Sort and WordCount. The generator runs as a Spark job in
the vanilla engine image through the local runner, so it scales with the machine. Rows are
derived from a seed by hashing, so the same rows and seed give the same data. Like the TPC
datasets, the result is staged and renamed into place only once its manifest is written.
"""

import math
import shutil
import uuid
from collections.abc import Callable
from dataclasses import dataclass
from datetime import UTC, datetime
from pathlib import Path

import duckdb

from velocia import __version__
from velocia.config.models import DataFormat, LocalCluster, Suite, SynthSpec
from velocia.datagen.duckdb_tpc import COMPRESSION, DatagenError, content_checksum, load_manifest
from velocia.datagen.manifest import (
    MANIFEST_FILE,
    DatasetFile,
    DatasetManifest,
    DatasetTable,
    dataset_checksum,
)
from velocia.experiment.expander import stable_hash
from velocia.families.spark.package import build_driver
from velocia.runners.base import AppSpec
from velocia.runners.local import TERAGEN_OUTPUT, LocalRunner

SEED = 42
ROWS_PER_PARTITION = 2_000_000
ROW_GROUP_BYTES = 100 * 1024 * 1024
GENERATOR_IMAGE = "velocia/engine-spark-vanilla:3.5.9"


@dataclass(frozen=True)
class SparkSuite:
    table: str
    label: str
    generator: str  # name in the driver's GENERATORS and in the manifest
    bytes_per_row: int  # uncompressed, for the row-group size


SPARK_SUITES = {
    Suite.tera: SparkSuite("tera", "TeraSort-style data generated by Velocia", "tera", 100),
    Suite.text: SparkSuite("text", "Text generated by Velocia (Sort, WordCount)", "text", 60),
    Suite.synth: SparkSuite("fact", "Edge-case data generated by Velocia (synth)", "synth", 64),
}


def spark_dataset_id(suite: Suite, rows: int, data_format: DataFormat) -> str:
    return f"{suite.value}-rows{rows}-{data_format.value}"


def synth_dataset_id(spec: SynthSpec, data_format: DataFormat) -> str:
    """Named by a hash of every generator parameter, seed included."""
    return f"synth-{stable_hash({'synth': spec.model_dump(mode='json')})[:12]}-{data_format.value}"


def tera_dataset_id(rows: int, data_format: DataFormat) -> str:
    return spark_dataset_id(Suite.tera, rows, data_format)


def generate_tera(
    rows: int,
    data_format: DataFormat,
    out_dir: Path,
    drivers_dir: Path,
    cores: int,
    progress: Callable[[str], None] = lambda _: None,
    image: str = GENERATOR_IMAGE,
) -> tuple[DatasetManifest, bool]:
    return generate_spark_suite(
        Suite.tera, rows, data_format, out_dir, drivers_dir, cores, progress, image
    )


def generate_spark_suite(
    suite: Suite,
    rows: int,
    data_format: DataFormat,
    out_dir: Path,
    drivers_dir: Path,
    cores: int,
    progress: Callable[[str], None] = lambda _: None,
    image: str = GENERATOR_IMAGE,
    synth: SynthSpec | None = None,
) -> tuple[DatasetManifest, bool]:
    """Generate a ``tera``, ``text`` or ``synth`` dataset (``synth`` takes ``synth``; its
    ``rows`` is the spec's)."""
    spec = SPARK_SUITES[suite]
    if suite is Suite.synth:
        synth = synth or SynthSpec()
        rows = synth.rows
        expected = {"fact": synth.rows, "dim": synth.keys}
        ds_id = synth_dataset_id(synth, data_format)
        params: dict[str, float | int | str] = synth.model_dump(mode="json")
        seed = synth.seed
        partitions = synth.files
    else:
        expected = {spec.table: rows}
        ds_id = spark_dataset_id(suite, rows, data_format)
        partitions = max(1, math.ceil(rows / ROWS_PER_PARTITION))
        params = {"rows": rows, "partitions": partitions}
        seed = SEED
    if rows <= 0:
        raise DatagenError("rows must be > 0")
    location = (out_dir / ds_id).resolve()
    if location.exists():
        if not (location / MANIFEST_FILE).is_file():
            raise DatagenError(f"{location} exists but has no {MANIFEST_FILE}; delete it first")
        return load_manifest(location), False

    runner = LocalRunner(
        LocalCluster(runner="local", executors=1, executor_cores=cores, executor_memory="2g")
    )
    problems = runner.check()
    if not problems and not runner.image_present(image):
        problems.append(f"image {image} not found; build it: velocia engines build spark-vanilla")
    if problems:
        raise DatagenError("; ".join(problems))

    progress(f"Generating {rows:,} {suite.value} rows ({partitions} files) with Apache Spark")
    out_dir.mkdir(parents=True, exist_ok=True)
    run_id = f"{spec.generator}gen-{uuid.uuid4().hex[:8]}"
    app = AppSpec(
        run_id=run_id,
        image=image,
        spark_conf={
            "spark.sql.parquet.compression.codec": COMPRESSION[data_format],
            "spark.hadoop.parquet.block.size": str(ROW_GROUP_BYTES),
        },
        driver=build_driver(drivers_dir),
        task="teragen",
        mode="cold",
        reps=[],
        warmup=False,
        units=[],
        dataset_location=out_dir,  # mounted read-only; teragen writes into the work dir
        tables=[],
        timeout_per_unit_s=24 * 3600,
        app_timeout_s=24 * 3600,
        teragen={
            "rows": rows,
            "seed": seed,
            "partitions": partitions,
            "generator": spec.generator,
            "synth": synth.model_dump(mode="json") if synth is not None else None,
        },
    )
    result = runner.run(app)
    staging = out_dir / f".{ds_id}.tmp-{uuid.uuid4().hex[:8]}"
    try:
        generated = result.work_dir / TERAGEN_OUTPUT
        if result.status != "finished" or not generated.is_dir():
            raise DatagenError(
                f"{suite.value} generation {result.status}:\n{result.log_tail[-2000:]}"
            )
        staging.mkdir()
        tables = []
        for table, table_rows in expected.items():
            table_dir = staging / table
            table_dir.mkdir()
            for part in sorted((generated / table).glob("part-*.parquet")):
                shutil.move(str(part), table_dir / part.name)
            progress(f"Computing the content checksum of {table}")
            with duckdb.connect() as con:
                written_rows, checksum = content_checksum(con, table_dir / "*.parquet")
            if written_rows != table_rows:
                raise DatagenError(f"{table}: wrote {written_rows} rows, expected {table_rows}")
            files = [
                DatasetFile(path=f"{table}/{p.name}", bytes=p.stat().st_size)
                for p in sorted(table_dir.iterdir())
            ]
            tables.append(DatasetTable(name=table, rows=table_rows, checksum=checksum, files=files))
        all_files = [f for t in tables for f in t.files]
        manifest = DatasetManifest(
            dataset_id=ds_id,
            suite=suite,
            label=spec.label,
            generator=f"velocia-{spec.generator}gen",
            generator_version=__version__,
            generator_params=params,
            seed=seed,
            scale=float(rows),
            data_format=data_format,
            compression=COMPRESSION[data_format],
            row_group_size=ROW_GROUP_BYTES // spec.bytes_per_row,
            location=str(location),
            tables=tables,
            files=len(all_files),
            bytes=sum(f.bytes for f in all_files),
            checksum=dataset_checksum(tables),
            created_at=datetime.now(UTC),
            velocia_version=__version__,
        )
        (staging / MANIFEST_FILE).write_text(manifest.model_dump_json(indent=2) + "\n", "utf-8")
        staging.rename(location)
    finally:
        shutil.rmtree(result.work_dir, ignore_errors=True)
        shutil.rmtree(staging, ignore_errors=True)
    return manifest, True
